-- Read-only supplemental evidence: parent cascades, indirect paths and RPC exposure.
begin isolation level repeatable read read only;
select jsonb_build_object(
 'captured_at',current_timestamp,'read_only',current_setting('transaction_read_only'),
 'parents',(select jsonb_agg(jsonb_build_object('table',c.oid::regclass::text,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl,'policies',(select jsonb_agg(to_jsonb(p)) from pg_policies p where p.schemaname=n.nspname and p.tablename=c.relname),'effective',(select jsonb_agg(jsonb_build_object('role',r.rolname,'schema_usage',has_schema_privilege(r.oid,n.oid,'USAGE'),'delete',has_table_privilege(r.oid,c.oid,'DELETE'),'truncate',has_table_privilege(r.oid,c.oid,'TRUNCATE'))) from pg_roles r where r.rolname in ('anon','authenticated','service_role')))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.oid in ('public.organizations'::regclass,'auth.users'::regclass)),
 'policy_dependencies',(select jsonb_agg(distinct jsonb_build_object('function',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'acl',p.proacl,'owner',pg_get_userbyid(p.proowner))) from pg_depend d join pg_proc p on p.oid=d.refobjid where d.classid='pg_policy'::regclass and d.refclassid='pg_proc'::regclass and d.objid in (select oid from pg_policy where polrelid in ('public.profiles'::regclass,'public.organizations'::regclass))),
 'dependent_views',(select jsonb_agg(distinct jsonb_build_object('view',c.oid::regclass::text,'definition',pg_get_viewdef(c.oid,true),'acl',c.relacl,'options',c.reloptions)) from pg_depend d join pg_rewrite rw on rw.oid=d.objid join pg_class c on c.oid=rw.ev_class where d.classid='pg_rewrite'::regclass and d.refclassid='pg_class'::regclass and d.refobjid='public.profiles'::regclass and c.relkind in ('v','m')),
 'public_function_inventory',(select jsonb_agg(jsonb_build_object('function',p.oid::regprocedure::text,'security_definer',p.prosecdef,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'config',p.proconfig,'definition',pg_get_functiondef(p.oid),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.prokind in ('f','p') and n.nspname='public' and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
 'other_callable_definers',(select jsonb_agg(jsonb_build_object('function',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'config',p.proconfig,'acl',p.proacl,'definition',pg_get_functiondef(p.oid))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.prokind in ('f','p') and p.prosecdef and n.nspname not in ('public','pg_catalog','information_schema') and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e') and ((has_schema_privilege('anon',n.oid,'USAGE') and has_function_privilege('anon',p.oid,'EXECUTE')) or (has_schema_privilege('authenticated',n.oid,'USAGE') and has_function_privilege('authenticated',p.oid,'EXECUTE')))),
 'api_role_settings',(select jsonb_agg(jsonb_build_object('role',case when s.setrole=0 then 'ALL' else pg_get_userbyid(s.setrole) end,'setting',v.setting)) from pg_db_role_setting s cross join lateral unnest(s.setconfig) v(setting) where v.setting like 'pgrst.db_schemas=%' or v.setting like 'pgrst.db_extra_search_path=%'),
 'profile_rules',(select jsonb_agg(jsonb_build_object('name',r.rulename,'definition',pg_get_ruledef(r.oid))) from pg_rewrite r where r.ev_class='public.profiles'::regclass),
 'profile_indexes',(select jsonb_agg(jsonb_build_object('name',indexname,'definition',indexdef)) from pg_indexes where schemaname='public' and tablename='profiles')
);
rollback;
